<?php

declare(strict_types=1);

namespace App\SharedKernel\Domain\Value;

use Symfony\Component\Uid\Uuid as SymfonyUuid;

/**
 * Base for aggregate ids: UUID v7, so ids are generated by the domain (no round trip
 * to the database) and sort by creation time.
 */
abstract readonly class Uuid
{
    final private function __construct(private string $value)
    {
        if (!SymfonyUuid::isValid($value)) {
            throw new \InvalidArgumentException(sprintf('"%s" is not a valid UUID.', $value));
        }
    }

    public static function generate(): static
    {
        return new static(SymfonyUuid::v7()->toRfc4122());
    }

    public static function fromString(string $value): static
    {
        return new static(strtolower($value));
    }

    public function value(): string
    {
        return $this->value;
    }

    public function equals(self $other): bool
    {
        return $other instanceof static && $this->value === $other->value;
    }
}
